let data = msg.payload;
let influxData = [];

if (data.temperature) {
    influxData.push({
        measurement: "water_mixer",
        fields: {
            temperature: data.temperature,
            hotFlow: data.hotFlow || 0,
            coldFlow: data.coldFlow || 0,
            totalFlow: (data.hotFlow || 0) + (data.coldFlow || 0),
            pidActive: data.pidActive ? 1 : 0
        },
        timestamp: Date.now() * 1000000
    });
}

if (data.angle !== undefined) {
    influxData.push({
        measurement: "barrier",
        fields: {
            angle: data.angle,
            error: data.error ? 1 : 0,
            limitOpen: data.limitOpen ? 1 : 0,
            limitClosed: data.limitClosed ? 1 : 0
        },
        timestamp: Date.now() * 1000000
    });
}

msg.payload = influxData;
return msg;
